export const exerciseContext: Readonly<Record<1 | 2, Readonly<Record<string, string>>>> = {
  1: {
    "db.ts": "import { DatabaseSync } from 'node:sqlite';\n\nexport const createDatabase = (): DatabaseSync => {\n  const db = new DatabaseSync(':memory:');\n  db.exec(`\n    CREATE TABLE visits (\n      id TEXT PRIMARY KEY,\n      pet_name TEXT NOT NULL,\n      status TEXT NOT NULL CHECK (status IN ('reserved', 'checked_in', 'completed', 'cancelled'))\n    );\n    CREATE TABLE visit_cancellations (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      visit_id TEXT NOT NULL,\n      cancelled_at TEXT NOT NULL,\n      operated_by TEXT NOT NULL,\n      reason TEXT NOT NULL\n    );\n  `);\n  return db;\n};\n\nexport const withTransaction = <T>(db: DatabaseSync, run: () => T): T => {\n  db.exec(`BEGIN`);\n  try {\n    const result = run();\n    db.exec(`COMMIT`);\n    return result;\n  } catch (error) {\n    db.exec(`ROLLBACK`);\n    throw error;\n  }\n};\n",
    "visits.test.ts": "import assert from 'node:assert/strict';\nimport type { DatabaseSync } from 'node:sqlite';\nimport { beforeEach, describe, it } from 'node:test';\nimport { createDatabase } from './db.ts';\nimport { cancelVisit, checkInVisit, completeVisit, reserveVisit } from './visits.ts';\n\nconst visitId = 'visit-1';\nconst cancelInput = { visitId, reason: '飼い主の都合', operatedBy: '受付スタッフ' };\nconst secondCancelInput = { visitId, reason: '来院前に回復したため', operatedBy: '院長' };\nconst missingRecord = `来院キャンセルの記録がありません（visit_cancellations を visit_id = '${visitId}' で探しました）`;\n\nlet db: DatabaseSync;\n\nconst statusOf = (id: string) => db.prepare(`SELECT status FROM visits WHERE id = ?`).get(id)?.status;\nconst cancellationsOf = (id: string) =>\n  db.prepare(`SELECT * FROM visit_cancellations WHERE visit_id = ? ORDER BY id`).all(id);\n\nbeforeEach(() => {\n  db = createDatabase();\n  reserveVisit(db, { visitId, petName: 'ポチ' });\n});\n\ndescribe('既存の業務', () => {\n  it('予約した来院をキャンセルすると、来院の状態がキャンセルになる', () => {\n    cancelVisit(db, cancelInput);\n    assert.equal(statusOf(visitId), 'cancelled');\n  });\n\n  it('診察が終わった来院はキャンセルできない', () => {\n    completeVisit(db, { visitId });\n    assert.throws(() => cancelVisit(db, cancelInput), /キャンセルできません/);\n    assert.equal(statusOf(visitId), 'completed');\n  });\n\n  it('キャンセルできなかったときは、記録を残さない', () => {\n    completeVisit(db, { visitId });\n    assert.throws(() => cancelVisit(db, cancelInput));\n    assert.equal(cancellationsOf(visitId).length, 0);\n  });\n\n  it('来院の更新に失敗したら、記録も残らない', () => {\n    db.exec(`\n      CREATE TRIGGER reject_update BEFORE UPDATE ON visits\n      BEGIN\n        SELECT RAISE(ABORT, '更新に失敗しました');\n      END;\n    `);\n    assert.throws(() => cancelVisit(db, cancelInput), /更新に失敗しました/);\n    assert.equal(cancellationsOf(visitId).length, 0);\n  });\n\n  it('予約した来院を受け付けると、来院の状態が受付済みになる', () => {\n    checkInVisit(db, { visitId });\n    assert.equal(statusOf(visitId), 'checked_in');\n  });\n});\n\ndescribe('第2章 ステップ1', () => {\n  it('来院をキャンセルすると、来院キャンセルの記録が1行残る', () => {\n    cancelVisit(db, cancelInput);\n    assert.equal(cancellationsOf(visitId).length, 1, missingRecord);\n  });\n\n  it('キャンセルした人と理由を答えられる', () => {\n    cancelVisit(db, cancelInput);\n    const record = cancellationsOf(visitId)[0];\n    assert.ok(record, missingRecord);\n    assert.equal(\n      record.operated_by,\n      cancelInput.operatedBy,\n      'キャンセルした人を答えられません（operated_by を読みました）',\n    );\n    assert.equal(record.reason, cancelInput.reason, 'キャンセルの理由を答えられません（reason を読みました）');\n    assert.ok(\n      !Number.isNaN(Date.parse(String(record.cancelled_at))),\n      'キャンセルした時刻を答えられません（cancelled_at を読みました）',\n    );\n  });\n\n  it('同じ来院をもう一度キャンセルしても、前の記録は消えない', () => {\n    cancelVisit(db, cancelInput);\n    cancelVisit(db, secondCancelInput);\n    assert.deepEqual(\n      cancellationsOf(visitId).map((record) => record.reason),\n      [cancelInput.reason, secondCancelInput.reason],\n      '2回のキャンセルの理由が、2行で残っていません（reason を読みました）',\n    );\n  });\n\n  it('記録に失敗したら、来院のキャンセルも失敗する', () => {\n    db.exec(`\n      CREATE TRIGGER reject_record BEFORE INSERT ON visit_cancellations\n      BEGIN\n        SELECT RAISE(ABORT, '記録に失敗しました');\n      END;\n    `);\n    assert.throws(() => cancelVisit(db, cancelInput), /記録に失敗しました/, '記録の失敗が更新処理に伝わっていません');\n    assert.equal(statusOf(visitId), 'reserved');\n  });\n});\n",
    "visits.ts": "import type { DatabaseSync } from 'node:sqlite';\nimport { withTransaction } from './db.ts';\n\nexport const reserveVisit = (db: DatabaseSync, input: { visitId: string; petName: string }): void => {\n  db.prepare(`INSERT INTO visits (id, pet_name, status) VALUES (?, ?, 'reserved')`).run(input.visitId, input.petName);\n};\n\nexport const checkInVisit = (db: DatabaseSync, input: { visitId: string }): void => {\n  db.prepare(`UPDATE visits SET status = 'checked_in' WHERE id = ?`).run(input.visitId);\n};\n\nexport const completeVisit = (db: DatabaseSync, input: { visitId: string }): void => {\n  db.prepare(`UPDATE visits SET status = 'completed' WHERE id = ?`).run(input.visitId);\n};\n\nexport const cancelVisit = (db: DatabaseSync, input: { visitId: string }): void => {\n  withTransaction(db, () => {\n    const visit = db.prepare(`SELECT status FROM visits WHERE id = ?`).get(input.visitId);\n    if (visit === undefined) {\n      throw new Error('来院が見つかりません');\n    }\n    if (visit.status === 'completed') {\n      throw new Error('診察が終わった来院はキャンセルできません');\n    }\n    db.prepare(`UPDATE visits SET status = 'cancelled' WHERE id = ?`).run(input.visitId);\n  });\n};\n",
  },
  2: {
    "db.ts": "import { DatabaseSync } from 'node:sqlite';\n\nexport const createDatabase = (): DatabaseSync => {\n  const db = new DatabaseSync(':memory:');\n  db.exec(`\n    CREATE TABLE visits (\n      id TEXT PRIMARY KEY,\n      pet_name TEXT NOT NULL,\n      status TEXT NOT NULL CHECK (status IN ('reserved', 'checked_in', 'completed', 'cancelled'))\n    );\n    CREATE TABLE business_events (\n      event_id INTEGER PRIMARY KEY AUTOINCREMENT,\n      event_at TEXT NOT NULL,\n      event_name TEXT NOT NULL,\n      payload TEXT NOT NULL,\n      target_id TEXT NOT NULL,\n      target_type TEXT NOT NULL,\n      target_state TEXT NOT NULL\n    );\n  `);\n  return db;\n};\n\nexport const withTransaction = <T>(db: DatabaseSync, run: () => T): T => {\n  db.exec(`BEGIN`);\n  try {\n    const result = run();\n    db.exec(`COMMIT`);\n    return result;\n  } catch (error) {\n    db.exec(`ROLLBACK`);\n    throw error;\n  }\n};\n",
    "visits.test.ts": "import assert from 'node:assert/strict';\nimport type { DatabaseSync } from 'node:sqlite';\nimport { beforeEach, describe, it } from 'node:test';\nimport { createDatabase } from './db.ts';\nimport { cancelVisit, checkInVisit, completeVisit, reserveVisit } from './visits.ts';\n\nconst visitId = 'visit-1';\nconst cancelInput = { visitId, reason: '飼い主の都合', operatedBy: '受付スタッフ' };\nconst missingEvent =\n  `来院キャンセルの記録がありません（business_events を target_type = 'Visit'、target_id = '${visitId}' で探しました）`;\n\nlet db: DatabaseSync;\n\nconst statusOf = (id: string) => db.prepare(`SELECT status FROM visits WHERE id = ?`).get(id)?.status;\nconst eventsOf = (id: string) =>\n  db.prepare(`SELECT * FROM business_events WHERE target_type = 'Visit' AND target_id = ?`).all(id);\n\nbeforeEach(() => {\n  db = createDatabase();\n  reserveVisit(db, { visitId, petName: 'ポチ' });\n});\n\ndescribe('既存の業務', () => {\n  it('予約した来院をキャンセルすると、来院の状態がキャンセルになる', () => {\n    cancelVisit(db, cancelInput);\n    assert.equal(statusOf(visitId), 'cancelled');\n  });\n\n  it('診察が終わった来院はキャンセルできない', () => {\n    completeVisit(db, { visitId });\n    assert.throws(() => cancelVisit(db, cancelInput), /キャンセルできません/);\n    assert.equal(statusOf(visitId), 'completed');\n  });\n\n  it('キャンセルできなかったときは、記録を残さない', () => {\n    completeVisit(db, { visitId });\n    assert.throws(() => cancelVisit(db, cancelInput));\n    assert.equal(eventsOf(visitId).length, 0);\n  });\n\n  it('来院の更新に失敗したら、記録も残らない', () => {\n    db.exec(`\n      CREATE TRIGGER reject_update BEFORE UPDATE ON visits\n      BEGIN\n        SELECT RAISE(ABORT, '更新に失敗しました');\n      END;\n    `);\n    assert.throws(() => cancelVisit(db, cancelInput), /更新に失敗しました/);\n    assert.equal(eventsOf(visitId).length, 0);\n  });\n\n  it('予約した来院を受け付けると、来院の状態が受付済みになる', () => {\n    checkInVisit(db, { visitId });\n    assert.equal(statusOf(visitId), 'checked_in');\n  });\n});\n\ndescribe('第2章 ステップ2', () => {\n  it('来院をキャンセルすると、来院キャンセルの記録が1行残る', () => {\n    cancelVisit(db, cancelInput);\n    const events = eventsOf(visitId);\n    assert.equal(events.length, 1, missingEvent);\n    assert.equal(events[0]?.event_name, 'VisitCancelled');\n  });\n\n  it('キャンセルの記録に、キャンセル後の来院の状態が残る', () => {\n    cancelVisit(db, cancelInput);\n    const event = eventsOf(visitId)[0];\n    assert.ok(event, missingEvent);\n    assert.equal(JSON.parse(String(event.target_state)).status, 'cancelled');\n  });\n\n  it('記録に失敗したら、来院のキャンセルも失敗する', () => {\n    db.exec(`\n      CREATE TRIGGER reject_event BEFORE INSERT ON business_events\n      BEGIN\n        SELECT RAISE(ABORT, '記録に失敗しました');\n      END;\n    `);\n    assert.throws(() => cancelVisit(db, cancelInput), /記録に失敗しました/, '記録の失敗が更新処理に伝わっていません');\n    assert.equal(statusOf(visitId), 'reserved');\n  });\n\n  it('キャンセルした人と理由を答えられる', () => {\n    cancelVisit(db, cancelInput);\n    const answer = db.prepare(`\n      SELECT\n        event_at,\n        event_name,\n        payload ->> '$.operatedBy' AS operated_by,\n        payload ->> '$.reason' AS reason\n      FROM business_events\n      WHERE target_type = 'Visit' AND target_id = ?\n    `).get(visitId);\n    assert.ok(answer, missingEvent);\n    assert.equal(\n      answer.operated_by,\n      cancelInput.operatedBy,\n      'キャンセルした人を答えられません（payload の operatedBy を読みました）',\n    );\n    assert.equal(\n      answer.reason,\n      cancelInput.reason,\n      'キャンセルの理由を答えられません（payload の reason を読みました）',\n    );\n    assert.equal(answer.event_name, 'VisitCancelled');\n    assert.ok(!Number.isNaN(Date.parse(String(answer.event_at))), 'キャンセルした時刻を答えられません');\n  });\n});\n",
    "visits.ts": "import type { DatabaseSync } from 'node:sqlite';\nimport { withTransaction } from './db.ts';\n\nexport const reserveVisit = (db: DatabaseSync, input: { visitId: string; petName: string }): void => {\n  db.prepare(`INSERT INTO visits (id, pet_name, status) VALUES (?, ?, 'reserved')`).run(input.visitId, input.petName);\n};\n\nexport const checkInVisit = (db: DatabaseSync, input: { visitId: string }): void => {\n  db.prepare(`UPDATE visits SET status = 'checked_in' WHERE id = ?`).run(input.visitId);\n};\n\nexport const completeVisit = (db: DatabaseSync, input: { visitId: string }): void => {\n  db.prepare(`UPDATE visits SET status = 'completed' WHERE id = ?`).run(input.visitId);\n};\n\nexport const cancelVisit = (db: DatabaseSync, input: { visitId: string; reason: string; operatedBy: string }): void => {\n  withTransaction(db, () => {\n    const visit = db.prepare(`SELECT status FROM visits WHERE id = ?`).get(input.visitId);\n    if (visit === undefined) {\n      throw new Error('来院が見つかりません');\n    }\n    if (visit.status === 'completed') {\n      throw new Error('診察が終わった来院はキャンセルできません');\n    }\n    db.prepare(`UPDATE visits SET status = 'cancelled' WHERE id = ?`).run(input.visitId);\n    db.prepare(`\n      INSERT INTO visit_cancellations (visit_id, cancelled_at, operated_by, reason)\n      VALUES (?, ?, ?, ?)\n    `).run(\n      input.visitId,\n      new Date().toISOString(),\n      input.operatedBy,\n      input.reason,\n    );\n  });\n};\n",
  },
};
